upsertArgs = (function () {
  var MAX = 2000;
  var parsed = JSON.parse(String(sectionsJson));
  var chunks = [];
  var sections = parsed.sections || [];
  for (var i = 0; i < sections.length; i++) {
    var title = sections[i].title || '';
    var text = (sections[i].content || '').trim();
    if (text.length === 0) continue;
    if (text.length <= MAX) {
      chunks.push({ text: (title ? title + '\n' : '') + text, title: title });
    } else {
      var part = 1;
      for (var pos = 0; pos < text.length; pos += MAX) {
        var piece = text.substring(pos, Math.min(pos + MAX, text.length));
        chunks.push({ text: (title ? title + ' (' + part + ')\n' : '') + piece, title: title });
        part++;
      }
    }
  }
  return { store: store, file_id: file, chunks: chunks };
})();
